package com.fileservice.core

import java.io._
import java.nio.file._
import java.security._
import javax.crypto._
import javax.crypto.spec._
import java.util.Base64
import scala.util.{Try, Success, Failure}
import scala.collection.mutable

object CryptoConfig {
  private val KEY_ALGO = "AES"
  private val CIPHER_ALGO = "AES/GCM/NoPadding"
  private val GCM_TAG_LENGTH = 128
  private val GCM_IV_LENGTH = 12

  def generateKey(): SecretKey = {
    val keyGen = KeyGenerator.getInstance(KEY_ALGO)
    keyGen.init(256)
    keyGen.generateKey()
  }

  def encrypt(data: Array[Byte], key: SecretKey): Array[Byte] = {
    val cipher = Cipher.getInstance(CIPHER_ALGO)
    val iv = new Array[Byte](GCM_IV_LENGTH)
    SecureRandom.getInstanceStrong.nextBytes(iv)
    val spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.ENCRYPT_MODE, key, spec)
    val encrypted = cipher.doFinal(data)
    iv ++ encrypted
  }

  def decrypt(data: Array[Byte], key: SecretKey): Array[Byte] = {
    val cipher = Cipher.getInstance(CIPHER_ALGO)
    val iv = data.take(GCM_IV_LENGTH)
    val ciphertext = data.drop(GCM_IV_LENGTH)
    val spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv)
    cipher.init(Cipher.DECRYPT_MODE, key, spec)
    cipher.doFinal(ciphertext)
  }
}

trait FileProcessor {
  def process(input: InputStream, metadata: Map[String, String]): Array[Byte]
  def supportedExtensions: Set[String]
}

class TextProcessor extends FileProcessor {
  override def process(input: InputStream, metadata: Map[String, String]): Array[Byte] = {
    val content = new String(input.readAllBytes(), "UTF-8")
    content.getBytes("UTF-8")
  }
  override def supportedExtensions: Set[String] = Set(".txt", ".log", ".csv")
}

class BinaryProcessor extends FileProcessor {
  override def process(input: InputStream, metadata: Map[String, String]): Array[Byte] = {
    input.readAllBytes()
  }
  override def supportedExtensions: Set[String] = Set(".bin", ".dat")
}

object ProcessorRegistry {
  private val ALLOWED_PACKAGE_PREFIX = "com.fileservice"

  private val defaultProcessors: Map[String, String] = Map(
    "text" -> "com.fileservice.core.TextProcessor",
    "binary" -> "com.fileservice.core.BinaryProcessor"
  )

  private val customProcessors: mutable.Map[String, String] = mutable.Map.empty

  def registerProcessor(name: String, className: String): Either[String, Unit] = {
    if (!validateClassName(className)) {
      Left(s"Invalid processor class: $className")
    } else {
      customProcessors(name) = className
      Right(())
    }
  }

  private def validateClassName(className: String): Boolean = {
    val normalized = className.replace('/', '.').trim
    normalized.startsWith(ALLOWED_PACKAGE_PREFIX) &&
      !normalized.contains("..") &&
      normalized.matches("^[a-zA-Z][a-zA-Z0-9.]*[a-zA-Z0-9]$")
  }

  def resolveProcessor(processorType: String): Either[String, FileProcessor] = {
    val className = defaultProcessors.getOrElse(
      processorType,
      customProcessors.getOrElse(processorType, "")
    )
    if (className.isEmpty) {
      Left(s"Unknown processor type: $processorType")
    } else {
      instantiateProcessor(className)
    }
  }

  private def instantiateProcessor(className: String): Either[String, FileProcessor] = {
    if (!validateClassName(className)) {
      return Left(s"Processor class not in allowed package: $className")
    }
    Try {
      val clazz = Class.forName(className)
      if (!classOf[FileProcessor].isAssignableFrom(clazz)) {
        throw new SecurityException(s"Class does not implement FileProcessor: $className")
      }
      val instance = clazz.getDeclaredConstructor().newInstance()
      instance.asInstanceOf[FileProcessor]
    } match {
      case Success(processor) => Right(processor)
      case Failure(ex) => Left(s"Failed to instantiate processor: ${ex.getMessage}")
    }
  }
}

class EncryptedFileService(storageDir: Path) {
  private val encryptionKey = CryptoConfig.generateKey()

  def storeFile(
    fileName: String,
    inputStream: InputStream,
    processorType: String,
    metadata: Map[String, String]
  ): Either[String, String] = {
    val sanitizedName = sanitizeFileName(fileName)
    if (sanitizedName.isEmpty) return Left("Invalid file name")

    ProcessorRegistry.resolveProcessor(processorType) match {
      case Left(err) => Left(err)
      case Right(processor) =>
        Try {
          val processed = processor.process(inputStream, metadata)
          val encrypted = CryptoConfig.encrypt(processed, encryptionKey)
          val targetPath = storageDir.resolve(sanitizedName + ".enc")
          Files.createDirectories(targetPath.getParent)
          Files.write(targetPath, encrypted)
          targetPath.toString
        } match {
          case Success(path) => Right(path)
          case Failure(ex) => Left(s"Storage failed: ${ex.getMessage}")
        }
    }
  }

  def retrieveFile(encryptedFileName: String): Either[String, Array[Byte]] = {
    val targetPath = storageDir.resolve(encryptedFileName)
    if (!targetPath.normalize().startsWith(storageDir.normalize())) {
      return Left("Path traversal detected")
    }
    Try {
      val encrypted = Files.readAllBytes(targetPath)
      CryptoConfig.decrypt(encrypted, encryptionKey)
    } match {
      case Success(data) => Right(data)
      case Failure(ex) => Left(s"Retrieval failed: ${ex.getMessage}")
    }
  }

  private def sanitizeFileName(name: String): String = {
    val cleaned = name.replaceAll("[^a-zA-Z0-9._-]", "")
    if (cleaned.contains("..") || cleaned.startsWith(".")) "" else cleaned
  }
}

object FileServiceApp {
  def main(args: Array[String]): Unit = {
    val storageDir = Paths.get(System.getProperty("storage.dir", "/tmp/encrypted-store"))
    val service = new EncryptedFileService(storageDir)
    println(s"Encrypted File Service initialized at $storageDir")
  }
}
